input.old_string:
.icon-btn {
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  color: var(--mute);
  background: transparent;
  border: none;
  border-radius: var(--radius-chip);
  width: 24px;
  height: 24px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.14s ease, background-color 0.14s ease;
}

input.new_string:
.icon-btn {
  font-family: "Segoe UI Symbol", "Apple Symbols", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  color: var(--mute);
  background: transparent;
  border: none;
  border-radius: var(--radius-chip);
  width: 24px;
  height: 24px;
  min-width: 24px;
  min-height: 24px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.14s ease, background-color 0.14s ease;
}
